-- Dev seed: the user me@example.com with password "test", who owns the seeded exercises and
-- trainings. Runs before the other seeds, which look the user up by email.
-- The bcrypt hash is generated by pgcrypto (requires the extension from the init migration).
INSERT INTO users (email, first_name, last_name, password_hash)
VALUES ('me@example.com', 'Max', 'Muster', crypt('test', gen_salt('bf', 10)))
ON CONFLICT (email) WHERE deleted_at IS NULL DO NOTHING;
